package com.vibeguard.samples.cards; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Pattern; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Stores provider-issued payment method tokens, never raw payment card data. */ @RestController @RequestMapping("/internal/payment-methods") public class CardController { private final Map<String,Method> methods=new ConcurrentHashMap<>(); @Value("${PAYMENT_VAULT_KEY:}") private String vaultKey; @PostMapping public ResponseEntity<Method> save(@RequestHeader("X-Payment-Vault-Key") String key,@Valid @RequestBody Request request){if(!allowed(key))return ResponseEntity.status(401).build();String id=UUID.randomUUID().toString();Method method=new Method(id,request.customerId(),request.providerPaymentMethodToken(),request.brand(),request.lastFour());methods.put(id,method);return ResponseEntity.status(201).body(method);}@GetMapping("/customer/{customerId}") public ResponseEntity<List<Method>> list(@RequestHeader("X-Payment-Vault-Key") String key,@PathVariable String customerId){if(!allowed(key))return ResponseEntity.status(401).build();return ResponseEntity.ok(methods.values().stream().filter(item->item.customerId().equals(customerId)).toList());}private boolean allowed(String key){return !vaultKey.isBlank()&&vaultKey.equals(key);}record Request(@NotBlank String customerId,@NotBlank String providerPaymentMethodToken,@NotBlank String brand,@Pattern(regexp="\\d{4}") String lastFour){}record Method(String id,String customerId,String providerPaymentMethodToken,String brand,String lastFour){} }
